import { useEffect, useState } from "react";
import Header from "./components/Header";
import Hero from "./components/Hero";
import Weather from "./components/Weather";
import News from "./components/News";
import Gallery from "./components/Gallery";
import Footer from "./components/Footer";
import { getWeather } from "./services/api";
import "./App.css";

function App() {
  const [cities, setCities] = useState(() => {
    try {
      return JSON.parse(
        localStorage.getItem("weather-cities") || "[]"
      );
    } catch {
      return [];
    }
  });

  const [selectedCity, setSelectedCity] = useState(() => {
    try {
      const saved = JSON.parse(
        localStorage.getItem("weather-cities") || "[]"
      );
      return saved.length ? saved[0].name : "";
    } catch {
      return "";
    }
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function addCity(cityName) {
    const name = cityName.trim();
    if (!name) return;

    const existing = cities.find(
      (city) => city.name.toLowerCase() === name.toLowerCase()
    );

    if (existing) {
      setSelectedCity(existing.name);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data = await getWeather(name);

      const city = {
        id: data.id,
        name: data.name,
        country: data.sys.country,
        temp: Math.round(data.main.temp),
        feels: Math.round(data.main.feels_like),
        humidity: data.main.humidity,
        wind: data.wind.speed,
        description: data.weather[0].description,
        icon: data.weather[0].icon,
        pressure: data.main.pressure,
        updated: Date.now(),
      };

      setCities((previous) => [...previous, city]);
      setSelectedCity(city.name);
    } catch {
      setError("Місто не знайдено. Перевір назву або API-ключ.");
    } finally {
      setLoading(false);
    }
  }

  async function refreshCity(cityName) {
    try {
      const data = await getWeather(cityName);

      setCities((previous) =>
        previous.map((city) =>
          city.name === cityName
            ? {
                ...city,
                temp: Math.round(data.main.temp),
                feels: Math.round(data.main.feels_like),
                humidity: data.main.humidity,
                wind: data.wind.speed,
                description: data.weather[0].description,
                icon: data.weather[0].icon,
                pressure: data.main.pressure,
                updated: Date.now(),
              }
            : city
        )
      );
    } catch {
      setError(`Не вдалося оновити погоду міста ${cityName}.`);
    }
  }

  function removeCity(cityName) {
    setCities((previous) =>
      previous.filter((city) => city.name !== cityName)
    );

    if (selectedCity === cityName) {
      const anotherCity = cities.find(
        (city) => city.name !== cityName
      );
      setSelectedCity(anotherCity?.name || "");
    }
  }

  useEffect(() => {
    localStorage.setItem("weather-cities", JSON.stringify(cities));
  }, [cities]);

  useEffect(() => {
    cities.forEach((city) => {
      refreshCity(city.name);
    });
  }, []);

  return (
    <div className="app">
      <Header />

      <main>
        <Hero onSearch={addCity} loading={loading} />

        {error && (
          <p className="error-message" role="alert">
            {error}
          </p>
        )}

        <Weather
          cities={cities}
          activeCity={cities.find(
            (city) => city.name === selectedCity
          )}
          selectedCity={selectedCity}
          onSelect={setSelectedCity}
          onAdd={addCity}
          onRemove={removeCity}
          onRefresh={refreshCity}
        />

        <News />
        <Gallery />
      </main>

      <Footer />
    </div>
  );
}

export default App;
